import csv, sys
reader = csv.DictReader(sys.stdin)
data = {}
for row in reader:
    family = row['Family']
    dosage = float(row['Dosage'])
    seed = row['Seed']
    acc = float(row['Accuracy'])
    key = (family, seed)
    if key not in data:
        data[key] = {}
    data[key][dosage] = acc

# Print s42 baselines and d100 deltas
print('=== Seed s42 d000 and d100 delta (for Table 1 verification) ===')
for (family, seed), doses in sorted(data.items()):
    if seed == 's42':
        d000 = doses.get(0.0, None)
        d100 = doses.get(1.0, None)
        if d000 and d100:
            print(f'{family} s42: d000={d000:.2f}%, d100={d100:.2f}%, delta={d100-d000:+.2f}pp')

# Print LLaMA data
print()
print('=== LLaMA data ===')
for (family, seed), doses in sorted(data.items()):
    if 'llama' in family.lower():
        print(f'{family} {seed}: {doses}')
